//! Which atlas tile each block face shows. The atlas is packed by build.rs from
//! every png in assets/images/blocks; which png each face uses is set per block in
//! assets/blocks.ron (see `Block::texture`).

use std::sync::LazyLock;

use amity_protocol::{inventory::item::Item, world::block::Block};
use bevy::prelude::*;

/// The block texture atlas and its name -> tile table, generated by build.rs from
/// assets/images/blocks. Embedded so native and web load it the same way.
pub mod atlas {
    include!(concat!(env!("OUT_DIR"), "/atlas.rs"));
}
pub const ATLAS: &[u8] = include_bytes!(concat!(env!("OUT_DIR"), "/atlas.png"));

/// The faces whose texture can differ, in the order `FACE_TILES` stores them
const FACE_NORMALS: [IVec3; 3] = [IVec3::Y, IVec3::X, IVec3::NEG_Y]; // top, side, bottom

/// Every block's atlas tile per face (top, side, bottom), indexed by block id.
/// Texture names are looked up in the atlas once, the first time a mesh needs
/// one, instead of once per face drawn
static FACE_TILES: LazyLock<Vec<[u32; 3]>> = LazyLock::new(|| {
    Block::all()
        .map(|block| FACE_NORMALS.map(|normal| tile_named(block.texture(normal))))
        .collect()
});

/// Which atlas tile a face shows. A name missing from the atlas shows the
/// magenta checker (build.rs already refuses blocks.ron naming a missing png)
pub fn face_tile(block: Block, normal: IVec3) -> u32 {
    let face = match normal {
        IVec3::Y => 0,
        IVec3::NEG_Y => 2,
        _ => 1,
    };
    FACE_TILES[block.id() as usize][face]
}

/// The atlas tile shown for an item: a block item's top face, else its icon
pub fn item_tile(item: Item) -> u32 {
    match item.places() {
        Some(block) => face_tile(block, IVec3::Y),
        None => tile_named(item.icon()),
    }
}

fn tile_named(name: &str) -> u32 {
    atlas::TILES
        .iter()
        .find(|(tile_name, _)| *tile_name == name)
        .map_or(atlas::MISSING, |&(_, tile)| tile)
}

/// Maps a 0..1 face UV into `tile`'s rectangle of the atlas. Pulled in by a sliver
/// of a pixel so float rounding at a face's edge never samples the next tile; any
/// more than that crops the edge pixels and visibly shifts the texture.
pub fn tile_uv(tile: u32, [u, v]: [f32; 2]) -> [f32; 2] {
    let size = Vec2::new(1.0 / atlas::COLUMNS as f32, 1.0 / atlas::ROWS as f32);
    let inset = size / (64 * atlas::TILE_PIXELS) as f32;
    let corner = Vec2::new((tile % atlas::COLUMNS) as f32, (tile / atlas::COLUMNS) as f32) * size;
    [
        corner.x + inset.x + u * (size.x - 2.0 * inset.x),
        corner.y + inset.y + v * (size.y - 2.0 * inset.y),
    ]
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::world::meshing::mesher::FACES;

    #[test]
    fn tile_uvs_stay_inside_their_tile() {
        let size = Vec2::new(1.0 / atlas::COLUMNS as f32, 1.0 / atlas::ROWS as f32);
        // tile 1 is column 1, row 0
        let [u0, v0] = tile_uv(1, [0.0, 0.0]);
        let [u1, v1] = tile_uv(1, [1.0, 1.0]);
        assert!(u0 > size.x && v0 > 0.0);
        assert!(u1 < 2.0 * size.x && v1 < size.y);
    }

    #[test]
    fn every_block_face_has_a_texture() {
        for block in Block::all().filter(|block| block.is_solid()) {
            for face in &FACES {
                assert_ne!(
                    face_tile(block, face.normal),
                    atlas::MISSING,
                    "{block:?} has no texture in assets/images/blocks"
                );
            }
        }
    }
}
